tailwind:
/* Arbitrary value: exactly the CSS gradient, any Tailwind v4 project. */
bg-[linear-gradient(45deg,#111111_0%,#888888_30%,#eeeeee_100%)]

/* Native utilities (two or three stops). bg-linear-<angle> interpolates in OKLAB by default in Tailwind v4; the modifier pins the space. */
bg-linear-45/srgb from-[#111111] via-[#888888] via-30% to-[#eeeeee]

/* Theme variable: use as class "bg-gradient". */
@theme {
  --background-image-gradient: linear-gradient(45deg, #111111 0%, #888888 30%, #eeeeee 100%);
}

/* Custom utility: use as class "bg-gradient". */
@utility bg-gradient {
  background-image: linear-gradient(45deg, #111111 0%, #888888 30%, #eeeeee 100%);
}

css-variables:
:root {
  --gradient-angle: 45deg;
  --gradient-color-1: #111111;
  --gradient-position-1: 0%;
  --gradient-color-2: #888888;
  --gradient-position-2: 30%;
  --gradient-color-3: #eeeeee;
  --gradient-position-3: 100%;
  --gradient: linear-gradient(var(--gradient-angle), var(--gradient-color-1) var(--gradient-position-1), var(--gradient-color-2) var(--gradient-position-2), var(--gradient-color-3) var(--gradient-position-3));
}

/* Usage: background: var(--gradient); */

